@namespace sv_312a9f6ae44b446e92f92a95f1378364.Components.Pages.Apply

<h4 class="mb-3">Cover Letter</h4>

<div class="mb-2">
    <textarea class="form-control" rows="10" maxlength="@MaxLength"
              value="@Text"
              @oninput="HandleInput"></textarea>
</div>

<div class="text-muted mb-3 text-end">
    @(Text?.Length ?? 0) / @MaxLength characters
</div>

@if (!string.IsNullOrEmpty(ValidationError))
{
    <div class="alert alert-danger">@ValidationError</div>
}

<div class="d-flex justify-content-between">
    <button class="btn btn-secondary" @onclick="OnBack">&larr; Back</button>
    <button class="btn btn-primary" @onclick="OnNext">Next &rarr;</button>
</div>

@code {
    [Parameter] public string Text { get; set; } = "";
    [Parameter] public EventCallback<string> TextChanged { get; set; }
    [Parameter] public int MaxLength { get; set; } = 2000;
    [Parameter] public string? ValidationError { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }
    [Parameter] public EventCallback OnNext { get; set; }

    private async Task HandleInput(ChangeEventArgs e)
    {
        var value = e.Value?.ToString() ?? "";
        if (value.Length > MaxLength)
            value = value[..MaxLength];
        Text = value;
        await TextChanged.InvokeAsync(value);
    }
}

@namespace sv_312a9f6ae44b446e92f92a95f1378364.Components.Pages.Apply
@using static sv_312a9f6ae44b446e92f92a95f1378364.Components.Pages.Apply.Apply

@if (IsSubmitted)
{
    <div class="text-center py-5">
        <div class="text-success mb-3" style="font-size: 3rem;">&#10003;</div>
        <h4 class="text-success">Application Submitted!</h4>
        <p class="lead">Your application ID is <strong>@SubmittedApplicationId</strong></p>
        <p class="text-muted">We will review your application and get back to you soon.</p>
    </div>
}
else
{
    <h4 class="mb-3">Review & Submit</h4>

    <!-- Personal Info -->
    <div class="mb-4">
        <div class="d-flex justify-content-between align-items-center mb-2">
            <h5 class="mb-0">Personal Information</h5>
            <a href="javascript:void(0)" @onclick='() => OnEditStep.InvokeAsync(1)'>Edit</a>
        </div>
        <dl class="row mb-0">
            <dt class="col-sm-3">Full Name</dt>
            <dd class="col-sm-9">@FullName</dd>
            <dt class="col-sm-3">Email</dt>
            <dd class="col-sm-9">@Email</dd>
            <dt class="col-sm-3">Phone</dt>
            <dd class="col-sm-9">@Phone</dd>
            <dt class="col-sm-3">Address</dt>
            <dd class="col-sm-9">@Address</dd>
        </dl>
    </div>

    <hr />

    <!-- Work History -->
    <div class="mb-4">
        <div class="d-flex justify-content-between align-items-center mb-2">
            <h5 class="mb-0">Work History</h5>
            <a href="javascript:void(0)" @onclick='() => OnEditStep.InvokeAsync(2)'>Edit</a>
        </div>
        @foreach (var entry in WorkEntries)
        {
            <div class="border-start border-3 border-primary ps-3 mb-3">
                <strong>@entry.Title</strong> at <strong>@entry.Company</strong><br />
                <small class="text-muted">
                    @entry.StartDate.ToString("MMM yyyy") &ndash;
                    @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy") ?? "N/A")
                </small>
                @if (!string.IsNullOrWhiteSpace(entry.Description))
                {
                    <p class="mb-0 mt-1">@entry.Description</p>
                }
            </div>
        }
    </div>

    <hr />

    <!-- References -->
    <div class="mb-4">
        <div class="d-flex justify-content-between align-items-center mb-2">
            <h5 class="mb-0">References</h5>
            <a href="javascript:void(0)" @onclick='() => OnEditStep.InvokeAsync(3)'>Edit</a>
        </div>
        @foreach (var r in References)
        {
            <div class="mb-2">
                <strong>@r.Name</strong> (@r.Relationship)<br />
                <small class="text-muted">@r.Email &bull; @r.Phone</small>
            </div>
        }
    </div>

    <hr />

    <!-- Cover Letter -->
    <div class="mb-4">
        <div class="d-flex justify-content-between align-items-center mb-2">
            <h5 class="mb-0">Cover Letter</h5>
            <a href="javascript:void(0)" @onclick='() => OnEditStep.InvokeAsync(4)'>Edit</a>
        </div>
        <div class="bg-light p-3 rounded" style="white-space: pre-wrap;">@CoverLetter</div>
    </div>

    @if (!string.IsNullOrEmpty(SubmitError))
    {
        <div class="alert alert-danger">@SubmitError</div>
    }

    <div class="d-flex justify-content-center mt-4">
        <button class="btn btn-success btn-lg" @onclick="OnSubmit" disabled="@IsSubmitting">
            @if (IsSubmitting)
            {
                <span class="spinner-border spinner-border-sm me-2" role="status"></span>
                <span>Submitting...</span>
            }
            else
            {
                <span>Submit Application</span>
            }
        </button>
    </div>
}

