@page "/apply"
@using sv_312a9f6ae44b446e92f92a95f1378364.Models
@rendermode InteractiveServer
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="container py-4" style="max-width: 800px;">
    <h2 class="mb-4">Job Application</h2>

    <StepIndicator CurrentStep="currentStep"
                   CompletedSteps="completedSteps"
                   OnStepClicked="GoToStep" />

    <div class="card mt-4">
        <div class="card-body">
            @if (currentStep == 1)
            {
                <StepPersonalInfo FullName="@fullName" Email="@email" Phone="@phone" Address="@address"
                                  FullNameChanged="v => fullName = v"
                                  EmailChanged="v => email = v"
                                  PhoneChanged="v => phone = v"
                                  AddressChanged="v => address = v"
                                  ValidationError="@validationError"
                                  OnNext="HandlePersonalInfoNext" />
            }
            else if (currentStep == 2)
            {
                <StepWorkHistory Entries="workEntries"
                                 ValidationError="@validationError"
                                 OnBack="GoBack"
                                 OnNext="HandleWorkHistoryNext" />
            }
            else if (currentStep == 3)
            {
                <StepReferences References="references"
                                ValidationError="@validationError"
                                OnBack="GoBack"
                                OnNext="HandleReferencesNext" />
            }
            else if (currentStep == 4)
            {
                <StepCoverLetter @bind-Text="coverLetter"
                                 MaxLength="2000"
                                 ValidationError="@validationError"
                                 OnBack="GoBack"
                                 OnNext="HandleCoverLetterNext" />
            }
            else if (currentStep == 5)
            {
                <StepReview FullName="@fullName" Email="@email" Phone="@phone" Address="@address"
                            WorkEntries="workEntries" References="references" CoverLetter="@coverLetter"
                            IsSubmitting="isSubmitting" IsSubmitted="isSubmitted"
                            SubmittedApplicationId="submittedAppId"
                            SubmitError="@submitError"
                            OnEditStep="GoToStep"
                            OnSubmit="HandleSubmit" />
            }
        </div>
    </div>
</div>

@code {
    private int currentStep = 1;
    private HashSet<int> completedSteps = new();
    private string? validationError;

    // Step 1 state
    private string fullName = "";
    private string email = "";
    private string phone = "";
    private string address = "";

    // Step 2 state
    private List<WorkEntryModel> workEntries = new() { new WorkEntryModel() };

    // Step 3 state
    private List<ReferenceModel> references = new() { new ReferenceModel(), new ReferenceModel() };

    // Step 4 state
    private string coverLetter = "";

    // Step 5 state
    private bool isSubmitting;
    private bool isSubmitted;
    private int submittedAppId;
    private string? submitError;

    private void GoToStep(int step)
    {
        if (step < currentStep || completedSteps.Contains(step))
        {
            validationError = null;
            currentStep = step;
        }
    }

    private void GoBack()
    {
        validationError = null;
        currentStep--;
    }

    private void AdvanceTo(int step)
    {
        completedSteps.Add(currentStep);
        validationError = null;
        currentStep = step;
    }

    private async Task HandlePersonalInfoNext()
    {
        if (string.IsNullOrWhiteSpace(fullName) || string.IsNullOrWhiteSpace(email)
            || string.IsNullOrWhiteSpace(phone) || string.IsNullOrWhiteSpace(address))
        {
            validationError = "All fields are required.";
            return;
        }

        var emailValid = await ApplicationService.ValidateEmailAsync(email);
        if (!emailValid)
        {
            validationError = "Please enter a valid email address.";
            return;
        }

        AdvanceTo(2);
    }

    private void HandleWorkHistoryNext()
    {
        foreach (var entry in workEntries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title)
                || entry.StartDate == default)
            {
                validationError = "Company, title, and start date are required for each position.";
                return;
            }
        }
        AdvanceTo(3);
    }

    private void HandleReferencesNext()
    {
        foreach (var r in references)
        {
            if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Relationship)
                || string.IsNullOrWhiteSpace(r.Email) || string.IsNullOrWhiteSpace(r.Phone))
            {
                validationError = "All fields are required for each reference.";
                return;
            }
        }
        AdvanceTo(4);
    }

    private void HandleCoverLetterNext()
    {
        if (string.IsNullOrWhiteSpace(coverLetter))
        {
            validationError = "Please write a cover letter.";
            return;
        }
        AdvanceTo(5);
    }

    private async Task HandleSubmit()
    {
        isSubmitting = true;
        submitError = null;
        StateHasChanged();

        try
        {
            var personal = new PersonalInfo(fullName, email, phone, address);
            var work = new WorkHistory(workEntries.Select(e =>
                new WorkEntry(e.Company, e.Title, e.StartDate, e.IsCurrent ? null : e.EndDate, e.Description)).ToList());
            var refs = references.Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList();
            var app = new JobApplication(personal, work, refs, coverLetter);

            submittedAppId = await ApplicationService.SubmitApplicationAsync(app);
            isSubmitted = true;
            completedSteps.Add(5);
        }
        catch (Exception ex)
        {
            submitError = $"Submission failed: {ex.Message}";
        }
        finally
        {
            isSubmitting = false;
        }
    }

    // Mutable model classes for form binding
    public class WorkEntryModel
    {
        public string Company { get; set; } = "";
        public string Title { get; set; } = "";
        public DateTime StartDate { get; set; }
        public DateTime? EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string Description { get; set; } = "";
    }

    public class ReferenceModel
    {
        public string Name { get; set; } = "";
        public string Relationship { get; set; } = "";
        public string Email { get; set; } = "";
        public string Phone { get; set; } = "";
    }
}

