@namespace sv_312a9f6ae44b446e92f92a95f1378364.Components.Pages.Apply

<nav aria-label="Application steps" class="mb-3">
    <ol class="step-indicator d-flex list-unstyled justify-content-between p-0 m-0">
        @for (int i = 0; i < stepNames.Length; i++)
        {
            var step = i + 1;
            var isActive = step == CurrentStep;
            var isCompleted = CompletedSteps.Contains(step);
            var isClickable = isCompleted && !isActive;

            <li class="step-item text-center flex-fill @(isActive ? "active" : isCompleted ? "completed" : "dimmed")"
                role="button"
                tabindex="@(isClickable ? 0 : -1)"
                @onclick="() => { if (isClickable) OnStepClicked.InvokeAsync(step); }">
                <div class="step-circle mx-auto mb-1 @(isActive ? "bg-primary text-white" : isCompleted ? "bg-success text-white" : "bg-light text-muted border")">
                    @if (isCompleted && !isActive)
                    {
                        <span>&#10003;</span>
                    }
                    else
                    {
                        <span>@step</span>
                    }
                </div>
                <small class="@(isActive ? "fw-bold" : isCompleted ? "text-success" : "text-muted")">@stepNames[i]</small>
            </li>
        }
    </ol>
</nav>

@code {
    [Parameter] public int CurrentStep { get; set; }
    [Parameter] public HashSet<int> CompletedSteps { get; set; } = new();
    [Parameter] public EventCallback<int> OnStepClicked { get; set; }

    private static readonly string[] stepNames = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };
}

